from pathlib import Path
p=Path('app/src/main/kotlin/com/metrolist/music/ui/player/MiniPlayer.kt')
s=p.read_text()
old='''                    MiniPlayerSkipButton(\n                        previous = true,\n                        enabled = canSkipPrevious && !isListenTogetherGuest,\n                        tint = onSurfaceColor,\n                        onClick = { playerConnection.seekToPrevious() },\n                    )\n                    MiniPlayerSkipButton(\n                        previous = false,\n                        enabled = canSkipNext && !isListenTogetherGuest,\n                        tint = onSurfaceColor,\n                        onClick = { playerConnection.seekToNext() },\n                    )\n                    if (isCasting) {'''
new='''                    if (!showSecondaryActions) {\n                        MiniPlayerPlayPauseButton(\n                            playbackState = playbackState,\n                            isCasting = isCasting,\n                            castHandler = castHandler,\n                            tint = onSurfaceColor,\n                            enabled = !isListenTogetherGuest,\n                            playerConnection = playerConnection,\n                        )\n                    }\n                    MiniPlayerSkipButton(\n                        previous = true,\n                        enabled = canSkipPrevious && !isListenTogetherGuest,\n                        tint = onSurfaceColor,\n                        onClick = { playerConnection.seekToPrevious() },\n                    )\n                    MiniPlayerSkipButton(\n                        previous = false,\n                        enabled = canSkipNext && !isListenTogetherGuest,\n                        tint = onSurfaceColor,\n                        onClick = { playerConnection.seekToNext() },\n                    )\n                    if (isCasting) {'''
if old not in s: raise SystemExit('mini row anchor not found')
s=s.replace(old,new,1)
old2='''                    if (showSecondaryActions) {\n                        mediaMetadata?.let {\n                            it.artists.firstOrNull()?.id?.let { artistId ->\n                                Spacer(modifier = Modifier.width(8.dp))\n                                SubscribeButton(\n                                    artistId = artistId,\n                                    metadata = it,\n                                    primaryColor = primaryColor,\n                                    outlineColor = outlineColor,\n                                    onSurfaceColor = onSurfaceColor,\n                                )\n                            }\n                            Spacer(modifier = Modifier.width(4.dp))\n                            FavoriteButton(\n                                songId = it.id,\n                                errorColor = errorColor,\n                                outlineColor = outlineColor,\n                                onSurfaceColor = onSurfaceColor,\n                            )\n                        }\n                    }'''
new2='''                    mediaMetadata?.let {\n                        if (showSecondaryActions) {\n                            it.artists.firstOrNull()?.id?.let { artistId ->\n                                Spacer(modifier = Modifier.width(8.dp))\n                                SubscribeButton(\n                                    artistId = artistId,\n                                    metadata = it,\n                                    primaryColor = primaryColor,\n                                    outlineColor = outlineColor,\n                                    onSurfaceColor = onSurfaceColor,\n                                )\n                            }\n                            Spacer(modifier = Modifier.width(4.dp))\n                        } else {\n                            Spacer(modifier = Modifier.width(2.dp))\n                        }\n                        FavoriteButton(\n                            songId = it.id,\n                            errorColor = errorColor,\n                            outlineColor = outlineColor,\n                            onSurfaceColor = onSurfaceColor,\n                        )\n                    }'''
if old2 not in s: raise SystemExit('mini favorite anchor not found')
s=s.replace(old2,new2,1)
anchor='''@Composable\nprivate fun MiniPlayerSkipButton('''
helper='''@Composable\nprivate fun MiniPlayerPlayPauseButton(\n    playbackState: Int,\n    isCasting: Boolean,\n    castHandler: CastConnectionHandler?,\n    tint: Color,\n    enabled: Boolean,\n    playerConnection: PlayerConnection,\n) {\n    val isPlaying by playerConnection.isPlaying.collectAsState()\n    val castIsPlaying by castHandler?.castIsPlaying?.collectAsState() ?: remember { mutableStateOf(false) }\n    val playing = if (isCasting) castIsPlaying else isPlaying\n    IconButton(\n        onClick = {\n            if (isCasting) {\n                if (castIsPlaying) castHandler?.pause() else castHandler?.play()\n            } else if (playbackState == Player.STATE_ENDED) {\n                playerConnection.player.seekTo(0, 0)\n                playerConnection.player.playWhenReady = true\n            } else {\n                playerConnection.togglePlayPause()\n            }\n        },\n        enabled = enabled,\n        modifier = Modifier.size(40.dp),\n    ) {\n        Icon(\n            painter = painterResource(if (playing) R.drawable.pause else R.drawable.play),\n            contentDescription = stringResource(R.string.play_pause),\n            tint = tint.copy(alpha = if (enabled) 1f else 0.38f),\n            modifier = Modifier.size(22.dp),\n        )\n    }\n}\n\n'''+anchor
if anchor not in s: raise SystemExit('skip helper anchor not found')
s=s.replace(anchor,helper,1)
p.write_text(s)
